import re
import sys


def count_words(text):
    return len(re.findall(r"[A-Za-z0-9']+", text))


def count_sentences(text):
    terminators = re.split(r"[.!?]+", text)
    sentences = []
    for term in terminators:
        term = term.strip()
        if not term:
            continue
        if term == ".":
            prev_word = (
                text.rsplit(" ", 1)[-1].strip()
                if text and text.rsplit()[-1].strip() == "."
                else None
            )
            if prev_word and prev_word.lower() in {"mr", "mrs", "dr", "st"}:
                sentences[-1] += term
            else:
                sentences.append(term)
        else:
            sentences.append(term)
    return sum(1 for s in sentences if s.strip())


def count_paragraphs(text):
    return sum(1 for p in text.split("\n\n") if p.strip())


def main():
    text = sys.stdin.read()
    paragraphs = count_paragraphs(text)
    sentences = count_sentences(text)
    words = count_words(text)
    longest_word = max((word for word in re.findall(r"[A-Za-z0-9']+", text) if word), key=lambda x: len(x), default="-")
    print("paragraphs", paragraphs)
    print("sentences", sentences)
    print("words", words)
    print("longest", longest_word)


if __name__ == "__main__":
    main()
